-- onboarding_step: Execution state of one step of an application
CREATE TABLE onboarding_step (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  onboarding_application_id    uuid NOT NULL REFERENCES onboarding_application(id),
  step_code                    varchar(64) NOT NULL,
  step_type                    varchar(40) NOT NULL CHECK (step_type IN ('PHONE_VERIFICATION', 'EMAIL_VERIFICATION', 'PERSONAL_DETAILS', 'BUSINESS_DETAILS', 'ADDRESS', 'DOCUMENT_CAPTURE', 'SELFIE_LIVENESS', 'SCREENING', 'RISK_ASSESSMENT', 'UBO_DECLARATION', 'TAX_DECLARATION', 'PRODUCT_SELECTION', 'TERMS_ACCEPTANCE', 'SIGNATURE', 'CREDENTIAL_SETUP', 'MANUAL_REVIEW', 'CUSTOM')),
  sequence                     integer NOT NULL,
  status                       varchar(40) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'IN_PROGRESS', 'COMPLETED', 'FAILED', 'SKIPPED', 'WAITING_REVIEW')),
  input                        jsonb,
  output                       jsonb,
  attempts                     integer NOT NULL DEFAULT 0,
  started_at                   timestamptz,
  completed_at                 timestamptz,
  error                        varchar(500),
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_onboarding_step_1 UNIQUE (onboarding_application_id, step_code)
);
